CREATE TABLE rm_workspace_invitation_events (
 id INTEGER PRIMARY KEY,
 invitation_id TEXT NOT NULL CHECK(length(invitation_id)=36),
 event_type TEXT NOT NULL CHECK(event_type IN ('issued','delivery_confirmed','delivery_failed','accepted','cancelled')),
 token_hash TEXT CHECK(token_hash IS NULL OR (length(token_hash)=64 AND token_hash NOT GLOB '*[^0-9a-f]*')),
 token_key_version INTEGER CHECK(token_key_version IS NULL OR token_key_version >= 0),
 canonical_email TEXT CHECK(canonical_email IS NULL OR (length(canonical_email) BETWEEN 3 AND 320 AND canonical_email = lower(trim(canonical_email)))),
 email_hash TEXT CHECK(email_hash IS NULL OR (length(email_hash)=64 AND email_hash NOT GLOB '*[^0-9a-f]*')),
 workspace_role TEXT CHECK(workspace_role IS NULL OR workspace_role IN ('workspace_owner','member')),
 company_slug TEXT CHECK(company_slug IS NULL OR (length(company_slug) BETWEEN 1 AND 120 AND substr(company_slug,1,1) GLOB '[a-z0-9]' AND company_slug NOT GLOB '*[^a-z0-9-]*')),
 company_role TEXT CHECK(company_role IS NULL OR company_role IN ('owner','bookkeeper','reviewer','reader')),
 expires_at TEXT CHECK(expires_at IS NULL OR length(expires_at) BETWEEN 20 AND 30),
 user_id TEXT REFERENCES "user"(id),
 actor TEXT NOT NULL CHECK(length(actor) BETWEEN 3 AND 160),
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CHECK((event_type='issued' AND token_hash IS NOT NULL AND token_key_version IS NOT NULL AND canonical_email IS NOT NULL AND email_hash IS NOT NULL AND workspace_role IS NOT NULL AND company_slug IS NOT NULL AND company_role IS NOT NULL AND expires_at IS NOT NULL AND user_id IS NULL) OR (event_type='accepted' AND token_hash IS NULL AND token_key_version IS NULL AND canonical_email IS NULL AND email_hash IS NULL AND workspace_role IS NULL AND company_slug IS NULL AND company_role IS NULL AND expires_at IS NULL AND user_id IS NOT NULL) OR (event_type IN ('delivery_confirmed','delivery_failed','cancelled') AND token_hash IS NULL AND token_key_version IS NULL AND canonical_email IS NULL AND email_hash IS NULL AND workspace_role IS NULL AND company_slug IS NULL AND company_role IS NULL AND expires_at IS NULL AND user_id IS NULL))
);
CREATE INDEX rm_workspace_invitation_events_current_idx ON rm_workspace_invitation_events(invitation_id,id DESC);
CREATE UNIQUE INDEX rm_workspace_invitation_events_token_uidx ON rm_workspace_invitation_events(token_hash) WHERE token_hash IS NOT NULL;
CREATE UNIQUE INDEX rm_workspace_invitation_events_accepted_uidx ON rm_workspace_invitation_events(invitation_id) WHERE event_type='accepted';
CREATE TRIGGER rm_workspace_invitation_events_no_update BEFORE UPDATE ON rm_workspace_invitation_events BEGIN SELECT RAISE(ABORT, 'workspace invitation events are append-only'); END;
CREATE TRIGGER rm_workspace_invitation_events_no_delete BEFORE DELETE ON rm_workspace_invitation_events BEGIN SELECT RAISE(ABORT, 'workspace invitation events are append-only'); END;
